```python
def print_board(board):
    """Print the Tic Tac Toe board."""
    print("-" * 9)
    for row in board:
        print("| " + " | ".join(row) + " |")
    print("-" * 9)

def get_player_move():
    """Get the player's move as a string of two integers."""
    while True:
        move = input("Enter your move (e.g. 1 2): ").strip()
        if len(move) == 2:
            try:
                row, col = map(int, move.split())
                if 1 <= row <= 3 and 1 <= col <= 3:
                    return row, col
                else:
                    print("Invalid move. Please enter a number between 1 and 3.")
            except ValueError:
                print("Invalid move. Please enter two numbers separated by a space.")
        else:
            print("Invalid move. Please enter two numbers separated by a space.")

def is_valid_move(board, row, col):
    """Check if a move is valid on the board."""
    return 1 <= row <= 3 and 1 <= col <= 3 and board[row - 1][col - 1] == " "

def is_winner(board, player):
    """Check if a player has won."""
    return (
        (board[0][0] == player and board[0][1] == player and board[0][2] == player) or  # Top row
        (board[1][0] == player and board[1][1] == player and board[1][2] == player) or  # Middle row
        (board[2][0] == player and board[2][1] == player and board[2][2] == player) or  # Bottom row
        (board[0][0] == player and board[1][0] == player and board[2][0] == player) or  # Left column
        (board[0][1] == player and board[1][1] == player and board[2][1] == player) or  # Middle column
        (board[0][2] == player and board[1][2] == player and board[2][2] == player) or  # Right column
        (board[0][0] == player and board[1][1] == player and board[2][2] == player) or  # Top-left to bottom-right diagonal
        (board[0][2] == player and board[1][1] == player and board[2][0] == player)   # Top-right to bottom-left diagonal
    )

def main():
    board = [[" "] * 3 for _ in range(3)]
    current_player = "X"

    while True:
        print_board(board)
        row, col = get_player_move()
        if is_valid_move(board, row, col):
            board[row - 1][col - 1] = current_player

        if is_winner(board, current_player):
            print_board(board)
            print(f"{current_player} has won!")
            break
        elif all(cell != " " for row in board for cell in row):
            print_board(board)
            print("It's a draw!")
            break

        current_player = "O" if current_player == "X" else "X"

if __name__ == "__main__":
    main()
```

This program will continue to run until a player wins or a draw occurs. You can customize the game rules, such as the number of moves required to win or the conditions for a draw, by modifying the `is_winner` function.
